func TestShadowStrategy_PreviewRewind_LogsOnly(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)

	t.Chdir(dir)

	s := &ManualCommitStrategy{}

	// Logs-only point should return empty preview
