// If the branch is already checked out in another worktree, git won't allow
// a second checkout here. Point the user at that worktree and tell them to
// re-run the picker there — that preserves the selected-session flow (the
// picker resumes the exact session by its checkpoint), whereas suggesting
// `entire resume <branch>` would resume the branch's latest checkpoint and
// pick the wrong session when several share the branch.
if otherPath, ok := branchCheckedOutElsewhere(ctx, chosen.branch); ok {
	fmt.Fprintf(w, "Branch %q is already checked out in another worktree:\n", chosen.branch)
	fmt.Fprintf(w, "  %s\n", otherPath)
	if prompt := strings.TrimSpace(chosen.state.LastPrompt); prompt != "" {
		fmt.Fprintf(w, "\nResume this session (%q) there by running the picker in that worktree:\n",
			stringutil.TruncateRunes(stringutil.CollapseWhitespace(prompt), 50, "..."))
	} else {
		fmt.Fprintln(w, "\nResume this session there by running the picker in that worktree:")
	}
	// shellQuote the path so the copy-paste command is safe even for paths
	// containing spaces or shell metacharacters. The branch name is not part
	// of the command, so it can't inject shell tokens.
	fmt.Fprintf(w, "  cd %s && entire session resume\n", shellQuote(otherPath))
	return nil
}

